CREATE TABLE public.merchant_store_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,store_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,permission text NOT NULL DEFAULT 'administrator' CHECK(permission='administrator'),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,UNIQUE(user_id,store_id));
GRANT SELECT ON public.merchant_store_memberships TO authenticated;
GRANT ALL ON public.merchant_store_memberships TO service_role;
ALTER TABLE public.merchant_store_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own explicit store memberships" ON public.merchant_store_memberships FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.can_actor_manage_marca_store(p_actor uuid,p_store_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_actor IS NOT NULL AND(p_actor=p_store_id OR EXISTS(SELECT 1 FROM merchant_store_memberships m JOIN brand_account_owned_stores o ON o.store_profile_id=m.store_id JOIN brand_accounts b ON b.id=o.brand_account_id JOIN brand_account_owned_stores p ON p.brand_account_id=b.id AND p.slot=1 AND p.store_role='primary' AND p.store_profile_id=b.owner_profile_id JOIN profiles profile ON profile.id=m.store_id WHERE m.user_id=p_actor AND m.store_id=p_store_id AND m.active AND m.permission='administrator' AND b.owner_profile_id=p_actor AND profile.deleted_at IS NULL AND coalesce(profile.account_status,'active')='active' AND get_effective_store_plan(b.owner_profile_id)->>'plan'='marca' AND get_effective_store_plan(b.owner_profile_id)->>'planSource'='direct')) $$;
REVOKE ALL ON FUNCTION public.can_actor_manage_marca_store(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_actor_manage_marca_store(uuid,uuid) TO authenticated,service_role;
CREATE FUNCTION public.can_manage_owned_store(p_store_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT can_actor_manage_marca_store(auth.uid(),p_store_id) $$;
REVOKE ALL ON FUNCTION public.can_manage_owned_store(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_owned_store(uuid) TO authenticated,service_role;
CREATE FUNCTION public.merchant_request_store_id() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE chosen text;sid uuid;actor uuid:=auth.uid(); BEGIN chosen:=nullif(coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb->>'x-shopdrive-store-id',''); IF chosen IS NULL THEN RETURN actor; END IF; IF actor IS NULL OR chosen !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'store_access_denied' USING ERRCODE='42501'; END IF; sid:=chosen::uuid; IF NOT can_actor_manage_marca_store(actor,sid) THEN RAISE EXCEPTION 'store_access_denied' USING ERRCODE='42501'; END IF;RETURN sid;END $$;
REVOKE ALL ON FUNCTION public.merchant_request_store_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.merchant_request_store_id() TO anon,authenticated,service_role;
CREATE FUNCTION public.admin_set_marca_store_membership(p_user_id uuid,p_store_id uuid,p_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM assert_caller_is_admin();IF NOT EXISTS(SELECT 1 FROM brand_accounts b JOIN brand_account_owned_stores o ON o.brand_account_id=b.id WHERE b.owner_profile_id=p_user_id AND o.store_profile_id=p_store_id) THEN RAISE EXCEPTION 'store_access_denied' USING ERRCODE='42501'; END IF;INSERT INTO merchant_store_memberships(user_id,store_id,active,created_by) VALUES(p_user_id,p_store_id,p_active,auth.uid()) ON CONFLICT(user_id,store_id) DO UPDATE SET active=excluded.active;END $$;
REVOKE ALL ON FUNCTION public.admin_set_marca_store_membership(uuid,uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_marca_store_membership(uuid,uuid,boolean) TO authenticated;
INSERT INTO merchant_store_memberships(user_id,store_id,permission,active,created_by) SELECT b.owner_profile_id,o.store_profile_id,'administrator',true,o.created_by FROM brand_accounts b JOIN brand_account_owned_stores o ON o.brand_account_id=b.id JOIN brand_account_owned_stores p ON p.brand_account_id=b.id AND p.slot=1 AND p.store_profile_id=b.owner_profile_id WHERE b.owner_profile_id IS NOT NULL AND get_effective_store_plan(b.owner_profile_id)->>'plan'='marca' AND get_effective_store_plan(b.owner_profile_id)->>'planSource'='direct' ON CONFLICT(user_id,store_id) DO NOTHING;
CREATE FUNCTION public._managed_store_json(p_store_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles;o public.brand_account_owned_stores;plan jsonb;hostname text;paid_until timestamptz;BEGIN SELECT * INTO p FROM profiles WHERE id=p_store_id AND deleted_at IS NULL;IF NOT FOUND OR p.store_slug IS NULL THEN RAISE EXCEPTION 'store_unavailable' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM brand_account_owned_stores WHERE store_profile_id=p_store_id;plan:=get_effective_store_plan(p_store_id);hostname:=_active_v2_store_hostname(p_store_id);IF o.store_role='secondary' AND plan->>'planSource'='direct' AND plan->>'plan' IN('pro','premium') THEN SELECT current_period_end INTO paid_until FROM master_subscriptions WHERE user_id=p_store_id AND status='active' AND current_period_end>now() ORDER BY created_at DESC LIMIT 1;END IF;RETURN jsonb_build_object('storeId',p.id,'storeName',coalesce(p.store_name,p.full_name,'Loja'),'storeSlug',p.store_slug,'publicUrl',CASE WHEN hostname IS NOT NULL THEN 'https://'||hostname ELSE 'https://shopdrive.com.br/'||p.store_slug END,'status',coalesce(p.account_status,'active'),'storeRole',o.store_role,'plan',plan->>'plan','paidUntil',paid_until);END $$;
REVOKE ALL ON FUNCTION public._managed_store_json(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.get_my_store_context(p_store_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid:=coalesce(p_store_id,merchant_request_store_id());BEGIN IF NOT can_actor_manage_marca_store(auth.uid(),sid) THEN RAISE EXCEPTION 'store_access_denied' USING ERRCODE='42501';END IF;RETURN _managed_store_json(sid);END $$;
REVOKE ALL ON FUNCTION public.get_my_store_context(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_my_store_context(uuid) TO authenticated;
CREATE FUNCTION public.get_my_managed_marca_stores() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(_managed_store_json(o.store_profile_id) ORDER BY o.slot),'[]'::jsonb) FROM brand_account_owned_stores o WHERE can_actor_manage_marca_store(auth.uid(),o.store_profile_id) $$;
REVOKE ALL ON FUNCTION public.get_my_managed_marca_stores() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_my_managed_marca_stores() TO authenticated;
DO $policies$ DECLARE r record;q text;c text;command text;BEGIN FOR r IN SELECT * FROM pg_policies WHERE schemaname='public' AND tablename=ANY(ARRAY['profiles','products','product_categories','product_brands','product_images','product_option_groups','product_option_values','product_variants','product_variant_values','orders','order_items','store_customers','customer_profiles','customer_groups','customer_group_assignments','quotes','store_events','store_product_views','store_referrals','plan_trials','store_onboarding_state','invoices','master_subscriptions','payment_settings']) AND policyname NOT ILIKE '%admin%' AND policyname NOT ILIKE '%public%' AND policyname NOT ILIKE '%anyone%' AND policyname NOT ILIKE '%verified stores%' AND policyname NOT ILIKE '%customers can%' AND policyname NOT ILIKE '%order items insert%' AND(qual LIKE '%auth.uid()%' OR with_check LIKE '%auth.uid()%') LOOP q:=replace(replace(replace(r.qual,'has_role(auth.uid()','has_role(__ACTOR__'),'auth.uid()','public.merchant_request_store_id()'),'__ACTOR__','auth.uid()');c:=replace(replace(replace(r.with_check,'has_role(auth.uid()','has_role(__ACTOR__'),'auth.uid()','public.merchant_request_store_id()'),'__ACTOR__','auth.uid()');command:=format('ALTER POLICY %I ON public.%I',r.policyname,r.tablename);IF q IS NOT NULL THEN command:=command||' USING ('||q||')';END IF;IF c IS NOT NULL THEN command:=command||' WITH CHECK ('||c||')';END IF;EXECUTE command;END LOOP; FOR r IN SELECT * FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND(policyname ILIKE '%their own product images%' OR policyname ILIKE '%their category icons%' OR policyname ILIKE '%their brand logos%') LOOP command:=format('ALTER POLICY %I ON storage.objects',r.policyname);IF r.qual IS NOT NULL THEN command:=command||' USING ('||replace(r.qual,'auth.uid()','public.merchant_request_store_id()')||')';END IF;IF r.with_check IS NOT NULL THEN command:=command||' WITH CHECK ('||replace(r.with_check,'auth.uid()','public.merchant_request_store_id()')||')';END IF;EXECUTE command;END LOOP;END $policies$;
DO $functions$ DECLARE r record;d text;BEGIN FOR r IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('get_product_plan_usage','activate_product_with_plan_validation','validate_product_activation_limit','create_manual_store_customer','is_quote_owner','save_product_variant_matrix','update_manual_order','replace_manual_order_items','convert_quote_to_order') LOOP d:=replace(pg_get_functiondef(r.oid),'auth.uid()','public.merchant_request_store_id()');EXECUTE d;END LOOP;FOR r IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('get_store_plan_context','backfill_store_customers','recompute_store_onboarding_state') LOOP d:=pg_get_functiondef(r.oid);d:=replace(d,'auth.uid() <> p_store_id','public.merchant_request_store_id() <> p_store_id');d:=replace(d,'auth.uid() IS DISTINCT FROM p_store_id','public.merchant_request_store_id() IS DISTINCT FROM p_store_id');EXECUTE d;END LOOP;END $functions$;
CREATE FUNCTION public.get_my_selected_store_domain() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid:=merchant_request_store_id();d public.merchant_domains;host text;BEGIN IF sid=auth.uid() THEN RETURN get_my_custom_domain_v2();END IF;SELECT * INTO d FROM merchant_domains WHERE merchant_id=sid AND released_at IS NULL ORDER BY updated_at DESC LIMIT 1;host:=_active_v2_store_hostname(sid);RETURN jsonb_build_object('available',false,'ingress_ready',false,'records','[]'::jsonb,'domain',CASE WHEN d.id IS NULL THEN NULL ELSE jsonb_build_object('id',d.id,'domain',d.normalized_domain,'display_hostname',coalesce(host,d.normalized_domain),'flow_version',d.flow_version,'state',d.v2_state,'active',host IS NOT NULL,'released',false,'ownership_verified_at',d.ownership_verified_at,'dns_verified_at',d.dns_verified_at,'routing_status',d.routing_status,'ssl_status',d.ssl_status,'last_dns_check',d.last_dns_check,'needs_reverification',d.needs_reverification) END);END $$;
REVOKE ALL ON FUNCTION public.get_my_selected_store_domain() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_my_selected_store_domain() TO authenticated;